import{_ as i,o as a,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const m=JSON.parse('{"title":"多地图与场景切换导航","description":"","frontmatter":{},"headers":[],"relativePath":"项目设计/多地图与场景切换导航.md","filePath":"项目设计/多地图与场景切换导航.md","lastUpdated":1777893104000}'),o={name:"项目设计/多地图与场景切换导航.md"};function c(r,l,h,t,s,n){return a(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="多地图与场景切换导航" tabindex="-1">多地图与场景切换导航 <a class="header-anchor" href="#多地图与场景切换导航" aria-label="Permalink to “多地图与场景切换导航”">​</a></h1><p>一句话摘要：这是一份面向多地图、多页面、多阶段项目的专题入口，重点关注场景切换时的数据保存、UI 生命周期、对象初始化和跨地图通信问题。</p><ul><li>适合对象：正在做多地图、多关卡、多页面流程的制作者</li><li>当前状态：已整理</li><li>可信度：<code>[高可信推断]</code></li><li>关联文档：<code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code>、<code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code>、<code>docs/脚本系统/专题研究/创游世界存档与云变量设计入门.md</code></li></ul><h2 id="这页适合解决什么问题" tabindex="-1">这页适合解决什么问题 <a class="header-anchor" href="#这页适合解决什么问题" aria-label="Permalink to “这页适合解决什么问题”">​</a></h2><ul><li>切地图后数据为什么丢了</li><li>为什么返回页面后 UI 状态错乱</li><li>地图对象、系统对象、UI 页面哪些该跟着切换，哪些不该</li><li>多地图项目里广播和数据作用域怎么放更稳</li></ul><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to “推荐阅读顺序”">​</a></h2><ol><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/创游世界存档与云变量设计入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界广播驱动项目结构实战.md</code></li></ol><h2 id="多地图项目的关键判断" tabindex="-1">多地图项目的关键判断 <a class="header-anchor" href="#多地图项目的关键判断" aria-label="Permalink to “多地图项目的关键判断”">​</a></h2><ul><li><code>[已确认]</code> 切换地图时，最容易出问题的是“数据归属不清”。</li><li><code>[已确认]</code> 页面临时状态不等于项目长期状态。</li><li><code>[已确认]</code> 需要跨地图保留的值，应尽量放在更稳定的系统层或存档层。</li><li><code>[高可信推断]</code> 地图越多，越需要在一开始就定义清楚：初始化、退出、恢复、同步这四类流程。</li></ul><h2 id="推荐关注的四个层次" tabindex="-1">推荐关注的四个层次 <a class="header-anchor" href="#推荐关注的四个层次" aria-label="Permalink to “推荐关注的四个层次”">​</a></h2><h3 id="地图层" tabindex="-1">地图层 <a class="header-anchor" href="#地图层" aria-label="Permalink to “地图层”">​</a></h3><p>负责：</p><ul><li>地图专属对象</li><li>场景内交互</li><li>临时事件与局部状态</li></ul><h3 id="系统层" tabindex="-1">系统层 <a class="header-anchor" href="#系统层" aria-label="Permalink to “系统层”">​</a></h3><p>负责：</p><ul><li>玩家长期状态</li><li>跨地图共享数据</li><li>任务推进与全局规则</li></ul><h3 id="ui-层" tabindex="-1">UI 层 <a class="header-anchor" href="#ui-层" aria-label="Permalink to “UI 层”">​</a></h3><p>负责：</p><ul><li>页面显示</li><li>操作入口</li><li>当前地图所需信息的展示</li></ul><h3 id="存档层" tabindex="-1">存档层 <a class="header-anchor" href="#存档层" aria-label="Permalink to “存档层”">​</a></h3><p>负责：</p><ul><li>长期保留的进度</li><li>跨重进仍需恢复的数据</li><li>云同步或本地恢复逻辑</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to “常见误区”">​</a></h2><ul><li>误区 1：每进一个地图都重新造一套核心数据。 <ul><li>后果：跨地图同步成本暴涨。</li></ul></li><li>误区 2：把页面状态误当成全局状态。 <ul><li>后果：关闭页面或切地图后状态丢失。</li></ul></li><li>误区 3：切换地图前后没有统一的初始化和回收逻辑。 <ul><li>后果：残留对象、重复广播、旧数据污染新地图。</li></ul></li></ul><h2 id="当前仍建议继续补强的部分" tabindex="-1">当前仍建议继续补强的部分 <a class="header-anchor" href="#当前仍建议继续补强的部分" aria-label="Permalink to “当前仍建议继续补强的部分”">​</a></h2><ul><li>场景切换生命周期模板</li><li>地图间任务推进示例</li><li>多地图 UI 复用策略</li><li>多地图项目中的性能与资源释放建议</li></ul><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to “关联阅读”">​</a></h2><ul><li><code>docs/项目设计/项目设计导航.md</code></li><li><code>docs/项目设计/项目结构与架构导航.md</code></li><li><code>docs/核心研究/广播与事件机制导航.md</code></li></ul>',28)])])}const _=i(o,[["render",c]]);export{m as __pageData,_ as default};
